import { calculateBirthChart } from '../src/lib/vedic/calculateBirthChart.js';
import { birthRangeError } from './_birthParams.js';
import { toKundaliLegacy } from '../src/lib/vedic/legacyAdapters.js';

async function getProKeralaToken(env) {
  const id = (env && env.VITE_PROKERALA_CLIENT_ID) || process.env.VITE_PROKERALA_CLIENT_ID;
  const secret = (env && env.VITE_PROKERALA_CLIENT_SECRET) || process.env.VITE_PROKERALA_CLIENT_SECRET;
  if (!id || !secret) return null;
  const res = await fetch('https://api.prokerala.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', client_id: id, client_secret: secret }),
  });
  const data = await res.json();
  return data.access_token || null;
}
function prokeralaDatetime(y, m, d, h, min, tz) {
  const sign = tz >= 0 ? '+' : '-';
  const abstz = Math.abs(tz);
  const tzH = String(Math.floor(abstz)).padStart(2, '0');
  const tzM = tz % 1 === 0.5 ? '30' : '00';
  return y+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0')+'T'+String(h).padStart(2,'0')+':'+String(min).padStart(2,'0')+':00'+sign+tzH+':'+tzM;
}
const RASHI_NAMES = ['Mesha','Vrisha','Mithuna','Karka','Simha','Kanya','Tula','Vrischika','Dhanu','Makara','Kumbha','Meena'];
const NK_DEV = {'Ashwini':'अश्विनी','Bharani':'भरणी','Krittika':'कृत्तिका','Rohini':'रोहिणी','Mrigashira':'मृगशिरा','Ardra':'आर्द्रा','Punarvasu':'पुनर्वसु','Pushya':'पुष्य','Ashlesha':'आश्लेषा','Magha':'मघा','Purva Phalguni':'पूर्वाफाल्गुनी','Uttara Phalguni':'उत्तराफाल्गुनी','Hasta':'हस्त','Chitra':'चित्रा','Swati':'स्वाती','Vishakha':'विशाखा','Anuradha':'अनुराधा','Jyeshtha':'ज्येष्ठा','Mula':'मूल','Purva Ashadha':'पूर्वाषाढ़ा','Uttara Ashadha':'उत्तराषाढ़ा','Shravana':'श्रवण','Dhanishtha':'धनिष्ठा','Shatabhisha':'शतभिषा','Purva Bhadrapada':'पूर्वाभाद्रपदा','Uttara Bhadrapada':'उत्तराभाद्रपदा','Revati':'रेवती'};

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=86400' },
  });
}

function findCurrentDasha(dashaPeriods, refDate) {
  if (!Array.isArray(dashaPeriods)) return null;
  const ref = refDate.getTime();
  const inRange = (p) => {
    const s = new Date(p.start).getTime();
    const e = new Date(p.end).getTime();
    return ref >= s && ref <= e;
  };
  const maha = dashaPeriods.find(inRange);
  if (!maha) return null;
  const antar = Array.isArray(maha.antardasha) ? maha.antardasha.find(inRange) : null;
  return {
    mahadasha: maha.name,
    mahadasha_start: maha.start,
    mahadasha_end: maha.end,
    antardasha: antar ? antar.name : '',
    antardasha_start: antar ? antar.start : null,
    antardasha_end: antar ? antar.end : null,
  };
}

function buildCacheKey(y, m, d, h, min, lat, lon, tz) {
  const rlat = Number(lat).toFixed(4);
  const rlon = Number(lon).toFixed(4);
  return [y, m, d, h, min, rlat, rlon, tz].join('-');
}

async function getSupabase(env) {
  const url = (env && env.SUPABASE_URL) || process.env.SUPABASE_URL;
  const key = (env && env.SUPABASE_SERVICE_ROLE_KEY) || process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) return null;
  const { createClient } = await import('@supabase/supabase-js');
  return createClient(url, key);
}

async function getCachedChart(sb, cacheKey) {
  if (!sb) return null;
  try {
    const { data, error } = await sb
      .from('vedic_chart_cache')
      .select('chart_data')
      .eq('cache_key', cacheKey)
      .maybeSingle();
    if (error || !data) return null;
    sb.from('vedic_chart_cache')
      .update({ last_accessed_at: new Date().toISOString() })
      .eq('cache_key', cacheKey)
      .then(() => {}, () => {});
    return data.chart_data;
  } catch (e) {
    return null;
  }
}

async function setCachedChart(sb, cacheKey, chartData, source = 'prokerala') {
  if (!sb) return;
  try {
    await sb.from('vedic_chart_cache').upsert({
      cache_key: cacheKey,
      chart_data: chartData,
      source,
      last_accessed_at: new Date().toISOString(),
    });
  } catch (e) {
    // cache write failure should never break the response
  }
}

// Local engine first (validated, offline, no rate limit). ProKerala is used
// only if the local engine throws — the fallback path is preserved per the
// integration contract, not removed. Returns { chart, source } or { error, status }.
async function computeChart(env, y, m, d, h, min, lat, lon, tz) {
  try {
    const result = await calculateBirthChart(
      { year: y, month: m, day: d, hour: h, minute: min, latitude: lat, longitude: lon, timezoneOffset: tz },
    );
    return { chart: toKundaliLegacy(result), source: 'local' };
  } catch (localErr) {
    // Fall back to ProKerala on any local-engine failure. The ProKerala
    // subscription has ended, so in practice this returns a 503 ("not
    // configured"); the local path is primary and is never removed.
    const pk = await fetchFromProKerala(env, y, m, d, h, min, lat, lon, tz);
    if (pk.error) {
      // Log loudly when BOTH the local engine and the fallback are unavailable,
      // so the failure is diagnosable. The visitor still gets a clear, honest
      // "temporarily unavailable" message (never a hang or a confusing error).
      console.error('[kundali] local engine failed AND ProKerala fallback unavailable —',
        'local:', String(localErr?.message || localErr), '| fallback:', pk.error);
      return { error: pk.error, status: pk.status, localError: String(localErr?.message || localErr) };
    }
    return { chart: pk.chart, source: 'prokerala' };
  }
}

// Validates that a ProKerala JSON response is a genuine success, not an
// error payload or a rate-limit response disguised as a 200. ProKerala
// returns status:"error" with an errors[] array on failures like rate
// limiting - we must never treat that as valid data.
function checkProKeralaStatus(data, label) {
  if (!data || data.status === 'error') {
    const detail = data?.errors?.[0]?.detail || 'unknown error';
    return `ProKerala ${label} failed: ${detail}`;
  }
  return null;
}

async function fetchFromProKerala(env, y, m, d, h, min, lat, lon, tz) {
  const token = await getProKeralaToken(env);
  if (!token) return { error: 'Kundali service not configured', status: 503 };
  const datetime = prokeralaDatetime(y, m, d, h, min, tz);
  const coords = lat+','+lon;
  const hdrs = { Authorization:'Bearer '+token };
  const [planetRes, bdRes, advRes] = await Promise.all([
    fetch('https://api.prokerala.com/v2/astrology/planet-position?datetime='+encodeURIComponent(datetime)+'&coordinates='+coords+'&ayanamsa=1', { headers: hdrs }),
    fetch('https://api.prokerala.com/v2/astrology/birth-details?datetime='+encodeURIComponent(datetime)+'&coordinates='+coords+'&ayanamsa=1', { headers: hdrs }),
    fetch('https://api.prokerala.com/v2/astrology/kundli/advanced?datetime='+encodeURIComponent(datetime)+'&coordinates='+coords+'&ayanamsa=1', { headers: hdrs }),
  ]);
  const [pd, bd, adv] = await Promise.all([planetRes.json(), bdRes.json(), advRes.json()]);

  // Explicitly check each response's own status field. A 200 HTTP status
  // does not guarantee success - ProKerala returns status:"error" with
  // a 200 in some cases (e.g. rate limiting), and silently proceeding
  // with empty defaults produces a wrong chart that then gets cached
  // forever. Fail loudly instead.
  const planetErr = checkProKeralaStatus(pd, 'planet-position');
  if (planetErr) return { error: planetErr, status: 502 };
  const bdErr = checkProKeralaStatus(bd, 'birth-details');
  if (bdErr) return { error: bdErr, status: 502 };
  const advErr = checkProKeralaStatus(adv, 'kundli/advanced');
  if (advErr) return { error: advErr, status: 502 };

  const rawPlanets = pd?.data?.planet_position || [];
  const nk = bd?.data?.nakshatra;
  const rashi = bd?.data?.chandra_rasi;

  // Ascendant is embedded inside planet_position as an entry named
  // "Ascendant", not a separate top-level field - this was the root
  // cause of an earlier silent-failure bug where asc = pd?.data?.ascendant
  // was always undefined, silently falling through to a wrong 0-degree
  // default when the array-search fallback also failed to run correctly
  // under certain response conditions.
  const ascEntry = rawPlanets.find(p => p.name === 'Ascendant');

  // Sanity check: a genuinely successful response always has 9 planets
  // plus Ascendant (10 entries) and a real nakshatra name. If this
  // isn't true, something is wrong even though status wasn't "error" -
  // refuse to proceed rather than compute a chart from incomplete data.
  if (!ascEntry || rawPlanets.length < 9 || !nk?.name) {
    return { error: 'ProKerala returned incomplete data (missing Ascendant, planets, or nakshatra)', status: 502 };
  }

  const dashaPeriods = adv?.data?.dasha_periods;
  const currentDasha = findCurrentDasha(dashaPeriods, new Date());

  const ascLon = ascEntry.longitude;
  const lagnaIdx = Math.floor(((ascLon % 360) + 360) % 360 / 30);
  const planets = rawPlanets.filter(p => p.name !== 'Ascendant').map(p => {
    const sIdx = Math.floor(((p.longitude % 360) + 360) % 360 / 30);
    return { name:p.name, sign:RASHI_NAMES[sIdx]||'Unknown', signIndex:sIdx+1, house:((sIdx-lagnaIdx+12)%12)+1, longitude:Number((p.longitude||0).toFixed(2)), retrograde:!!p.is_retrograde };
  });
  const nkName = nk?.name || 'Unknown';
  const rashiName = rashi?.name || null;

  return {
    chart: {
      lagna: { sign:RASHI_NAMES[lagnaIdx]||'Unknown', signIndex:lagnaIdx+1, degrees:Number((ascLon||0).toFixed(2)) },
      planets,
      nakshatra: { nakshatra:nkName, nakshatra_devanagari:NK_DEV[nkName]||nkName, pada:nk?.pada||1, confidence:'high', is_boundary:false },
      rashi: rashiName,
      rashi_devanagari: null,
      dasha: currentDasha,
      requires_birth_time: false,
    },
  };
}

async function handler(request, env) {
  if (request.method !== 'GET') return json({ error: 'Method not allowed' }, 405);
  const { searchParams } = new URL(request.url, 'http://localhost');
  const n = (k, def) => { const v = searchParams.get(k); return (v===null||v==='') ? def : Number(v); };
  const y=n('y'), m=n('m'), d=n('d');
  if (![y,m,d].every(v=>Number.isFinite(v))) return json({ error:'Missing y/m/d' }, 400);
  const h=n('h',12), min=n('min',0), lat=n('lat',28.6139), lon=n('lon',77.2090), tz=n('tz',5.5);
  // Part T: reject out-of-range input up front with a clean 400 (was falling through to
  // the ProKerala fallback and returning a 502, wasting a ProKerala call on garbage).
  const rangeErr = birthRangeError({ m, d, h, min, lat, lon, tz });
  if (rangeErr) return json({ error: rangeErr }, 400);

  try {
    const sb = await getSupabase(env);
    const cacheKey = buildCacheKey(y, m, d, h, min, lat, lon, tz);

    const cached = await getCachedChart(sb, cacheKey);
    // A cached entry is only valid if it carries the fields every current consumer
    // needs. Entries written before the legacy-adapter fix lack `doshas` (used by
    // /manglik and /kaal-sarp-dosha) and `dashaTimeline` (used by the Dasha deep-dive
    // and What's Ahead). Serving those would reproduce the original failure on a cache
    // HIT, so we treat a stale entry as a miss: recompute and overwrite the SAME row
    // (upsert on cache_key) — no real user data is deleted, it is refreshed in place.
    const cacheIsComplete = cached && cached.doshas && Array.isArray(cached.dashaTimeline);
    if (cacheIsComplete) {
      return json({ ...cached, _cache: 'hit' });
    }

    const result = await computeChart(env, y, m, d, h, min, lat, lon, tz);
    if (result.error) return json({ error: result.error }, result.status);

    await setCachedChart(sb, cacheKey, result.chart, result.source);

    return json({ ...result.chart, _cache: cached ? 'refreshed' : 'miss' });
  } catch(e) { return json({ error:'calc-failed', detail:String(e.message||e) }, 500); }
}
export const GET = handler;
